/** Applies goal progress and its optional account expense/reservation as one local state update. */
function saveGoalContribution(setState: StoreApi<FinanceState>['setState'], contribution: GoalContribution): { success: boolean; message: string } {
  let result: { success: boolean; message: string } = { success: false, message: 'Goal contribution could not be saved.' }
  setState((state) => {
    const existing = state.goalContributions.find((item) => item.id === contribution.id)
    const goal = state.goals.find((item) => item.id === contribution.goalId)
    const account = state.accounts.find((item) => item.id === contribution.accountId && !item.archived)
    if (!goal) { result = { success: false, message: 'Goal was not found.' }; return {} }
    if (!account) { result = { success: false, message: 'Select an active funding account.' }; return {} }
    if (!Number.isFinite(contribution.amount) || contribution.amount <= 0 || !contribution.date) { result = { success: false, message: 'Enter a valid amount and date.' }; return {} }
    const nextProgress = goal.currentAmount - (existing?.amount ?? 0) + contribution.amount
    if (nextProgress > goal.targetAmount + 0.005) { result = { success: false, message: 'This contribution exceeds the goal amount remaining.' }; return {} }

    const transactionId = contribution.type === 'paid' ? existing?.transactionId ?? `goal-contribution:${contribution.id}:payment` : undefined
    const transactions = state.transactions.filter((entry) => entry.type !== 'expense' || entry.id !== existing?.transactionId && entry.goalContributionId !== contribution.id)
    const otherGoalContributions = state.goalContributions.filter((item) => item.id !== contribution.id)
    const accountAvailable = accountAvailableBalance(account, transactions, state.transfers, state.contributions, state.balanceAdjustments, state.plannedSpending, otherGoalContributions, state.budgetSchedules, state.budgetOccurrences)
    if (contribution.amount > accountAvailable + 0.005) {
      result = { success: false, message: `Only ${accountAvailable.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} is available in ${account.name} after existing allocations.` }
      return {}
    }
    if (contribution.type === 'paid') transactions.unshift({ id: transactionId!, type: 'expense', amount: contribution.amount, date: contribution.date, category: 'Investment', description: `Goal contribution: ${goal.name}`, accountId: account.id, goalContributionId: contribution.id })

    const now = localDateTime()
    const nextContribution: GoalContribution = { ...contribution, transactionId, createdAt: existing?.createdAt ?? contribution.createdAt ?? now, updatedAt: now }
    result = { success: true, message: contribution.type === 'reserve' ? `${contribution.amount.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} reserved for ${goal.name}; ${account.name} physical balance is unchanged.` : `${contribution.amount.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} paid from ${account.name} for ${goal.name}.` }
    const beforeBalance = accountBalance(account, state.transactions, state.transfers, state.contributions, state.balanceAdjustments)
    const afterBalance = accountBalance(account, transactions, state.transfers, state.contributions, state.balanceAdjustments)
    return {
      transactions,
      goals: state.goals.map((item) => item.id === goal.id ? { ...item, currentAmount: nextProgress } : item),
      goalContributions: existing ? state.goalContributions.map((item) => item.id === contribution.id ? nextContribution : item) : [nextContribution, ...state.goalContributions],
      activityHistory: [createActivityEvent({ category: 'goals', action: existing ? 'edited' : 'created', entityType: 'goal_contribution', entityId: contribution.id, title: goal.name, description: `${contribution.type === 'reserve' ? 'Reserved' : 'Paid'} ${contribution.amount.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })}${contribution.notes ? ` · ${contribution.notes}` : ''}`, date: contribution.date, amount: contribution.type === 'paid' ? -contribution.amount : contribution.amount, accountId: account.id, beforeBalance, afterBalance }), ...state.activityHistory],
      notifications: appendNotification(state.notifications, createFinanceNotification({ id: `goal-contribution:${contribution.id}:${existing ? 'edited' : 'created'}`, type: 'goal_contribution', title: contribution.type === 'reserve' ? 'Goal money reserved' : 'Goal contribution paid', message: result.message, relatedEntityType: 'goal_contribution', relatedEntityId: contribution.id, priority: 'normal' })),
    }
  })
  return result
}

/** Applies a contribution edit and its linked payment ledger entry atomically. */
function saveContribution(setState: StoreApi<FinanceState>['setState'], contribution: Contribution, deductNow: boolean, forcePayNow = false): { success: boolean; message: string } {
  let result: { success: boolean; message: string } = { success: false, message: 'Contribution could not be saved.' }
  setState((state) => {
    const existing = state.contributions.find((item) => item.id === contribution.id)
    const contributionDate = contribution.contributionDate ?? contribution.date
    const today = localDate()
    const oldPaymentId = existing?.transactionId ?? `contribution:${contribution.id}:payment`
    const transactions = state.transactions.filter((entry) => entry.id !== oldPaymentId && !(entry.type === 'expense' && entry.contributionId === contribution.id))
    const accountId = contribution.sourceAccountId ?? contribution.accountId
    const now = localDateTime()
    let status: Contribution['status']
    let balanceEffect: Contribution['balanceEffect']
    let paidAt: string | undefined
    let transactionId: string | undefined

    if (forcePayNow) {
      const account = state.accounts.find((item) => item.id === accountId && !item.archived)
      if (!account) {
        result = { success: false, message: 'Select an active source account to pay this contribution.' }
        return {}
      }
      const balance = accountBalance(account, transactions, state.transfers, state.contributions, state.balanceAdjustments)
      if (contribution.amount > balance) {
        result = { success: false, message: `The selected account has ${balance.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} available, which is not enough for this contribution.` }
        return {}
      }
      status = 'paid'
      balanceEffect = 'deducted'
      paidAt = now
      transactionId = oldPaymentId
      transactions.unshift({ id: transactionId, type: 'expense', amount: contribution.amount, date: today, category: 'Others', description: `Contribution: ${contribution.title}`, accountId: account.id, contributionId: contribution.id })
    } else if (contributionDate < today) {
      status = 'paid'
      balanceEffect = 'historical_no_deduction'
      paidAt = existing?.balanceEffect === 'historical_no_deduction' ? existing.paidAt : undefined
    } else if (contributionDate > today) {
      status = 'scheduled'
      balanceEffect = 'none'
    } else if (deductNow) {
      const account = state.accounts.find((item) => item.id === accountId && !item.archived)
      if (!account) {
        result = { success: false, message: 'Select an active source account to deduct this contribution.' }
        return {}
      }
      const balance = accountBalance(account, transactions, state.transfers, state.contributions, state.balanceAdjustments)
      if (contribution.amount > balance) {
        result = { success: false, message: `The selected account has ${balance.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} available, which is not enough for this contribution.` }
        return {}
      }
      status = 'paid'
      balanceEffect = 'deducted'
      paidAt = existing?.balanceEffect === 'deducted' ? existing.paidAt ?? now : now
      transactionId = oldPaymentId
      transactions.unshift({ id: transactionId, type: 'expense', amount: contribution.amount, date: today, category: 'Others', description: `Contribution: ${contribution.title}`, accountId: account.id, contributionId: contribution.id })
    } else {
      status = 'pending'
      balanceEffect = 'none'
    }

    const nextContribution: Contribution = {
      ...contribution,
      date: contributionDate,
      contributionDate,
      sourceAccountId: accountId,
      accountId,
      status,
      balanceEffect,
      includeInExpenseAnalytics: contribution.includeInExpenseAnalytics ?? contribution.includeInAnalytics ?? false,
      paidAt,
      transactionId,
      createdAt: existing?.createdAt ?? contribution.createdAt ?? now,
      updatedAt: now,
      alreadyPaid: status === 'paid',
      alreadyReflected: balanceEffect === 'historical_no_deduction',
      includeInAnalytics: contribution.includeInExpenseAnalytics ?? contribution.includeInAnalytics ?? false,
    }
    result = { success: true, message: status === 'paid' && balanceEffect === 'deducted' ? `Contribution paid. ${contribution.amount.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} was deducted from ${state.accounts.find((item) => item.id === accountId)?.name} for ${contribution.title}.` : status === 'paid' ? 'Historical contribution recorded. Your current balance was not changed.' : status === 'scheduled' ? 'Contribution scheduled. No money was deducted.' : 'Contribution saved as pending. No money was deducted.' }
    const source = state.accounts.find((item) => item.id === accountId)
    return { transactions, contributions: existing ? state.contributions.map((item) => item.id === contribution.id ? nextContribution : item) : [nextContribution, ...state.contributions], activityHistory: [createActivityEvent({ category: 'contributions', action: existing ? 'edited' : status === 'paid' ? 'paid' : 'created', entityType: 'contribution', entityId: contribution.id, title: contribution.title, description: result.message, date: contributionDate, amount: status === 'paid' && balanceEffect === 'deducted' ? -contribution.amount : contribution.amount, accountId, beforeBalance: source && balanceEffect === 'deducted' ? accountBalance(source, state.transactions, state.transfers, state.contributions, state.balanceAdjustments) : undefined, afterBalance: source && balanceEffect === 'deducted' ? accountBalance(source, transactions, state.transfers, state.contributions, state.balanceAdjustments) : undefined }), ...state.activityHistory], notifications: appendNotification(state.notifications, createFinanceNotification({ id: `contribution:${contribution.id}:${existing ? 'edited' : status === 'paid' ? 'paid' : 'created'}`, type: 'contribution', title: status === 'paid' ? 'Contribution paid' : 'Contribution recorded', message: result.message, relatedEntityType: 'contribution', relatedEntityId: contribution.id, priority: 'normal' })) }
  })
  return result
}

function createActivityEvent(entry: Omit<ActivityHistoryEntry, 'id' | 'userId' | 'createdAt'>): ActivityHistoryEntry {
  return { ...entry, id: createId(), userId: 'local', createdAt: localDateTime() }
}

function createFinanceNotification(entry: Omit<FinanceNotification, 'userId' | 'createdAt'>): FinanceNotification {
  return { ...entry, userId: 'local', createdAt: localDateTime() }
}

function appendNotification(notifications: FinanceNotification[], notification: FinanceNotification): FinanceNotification[] {
  return notifications.some((item) => item.id === notification.id) ? notifications : [notification, ...notifications]
}

function budgetScheduleDates(schedule: BudgetSchedule): string[] {
  const cursor = new Date(`${schedule.startDate}T12:00:00`)
  const end = new Date(`${schedule.endDate}T12:00:00`)
  if (!Number.isFinite(cursor.getTime()) || !Number.isFinite(end.getTime()) || cursor > end) return []
  const dates: string[] = []
  while (cursor <= end) {
    if (!schedule.weekdays.length || schedule.weekdays.includes(cursor.getDay())) dates.push(localDate(cursor))
    cursor.setDate(cursor.getDate() + 1)
  }
  return dates
}

/** Updates or appends a transaction in persisted local state. */
function upsertTransaction(entry: Transaction) {
  useFinanceStore.setState((state) => {
    const existing = state.transactions.find((item) => item.id === entry.id)
    let accounts = state.accounts
    let accountId = entry.accountId
    if (entry.type !== 'saving' && !accountId) {
      let account = accounts.find((item) => !item.archived)
      if (!account) {
        account = { id: 'account-default-cash', name: 'Cash', institution: 'Cash', kind: 'Cash', openingBalance: 0, includeInTotal: true, archived: false, color: '#3ba7ff', icon: 'wallet', nickname: '' }
        accounts = [...accounts, account]
      }
      accountId = account.id
    }
    const nextEntry = { ...entry, ...(accountId ? { accountId } : {}) } as Transaction
    const transactions = existing ? state.transactions.map((item) => item.id === nextEntry.id ? nextEntry : item) : [nextEntry, ...state.transactions]
    const account = accounts.find((item) => item.id === accountId)
    const previousBalance = account && existing?.accountId === accountId ? accountBalance(account, state.transactions, state.transfers, state.contributions, state.balanceAdjustments) : undefined
    const nextBalance = account && existing?.accountId === accountId ? accountBalance(account, transactions, state.transfers, state.contributions, state.balanceAdjustments) : undefined
    const category = nextEntry.type === 'expense' ? 'expenses' : nextEntry.type === 'income' ? 'income' : 'savings'
    const title = nextEntry.type === 'expense' ? nextEntry.description : nextEntry.type === 'income' ? nextEntry.source : nextEntry.savingType
    const description = nextEntry.type === 'expense' ? nextEntry.description : nextEntry.type === 'income' ? nextEntry.notes || nextEntry.source : nextEntry.mode === 'opening' ? 'Existing savings classified' : 'Savings transfer classified'
    return {
      accounts,
      transactions,
      activityHistory: [createActivityEvent({ category, action: existing ? 'edited' : 'created', entityType: nextEntry.type, entityId: nextEntry.id, title, description, date: nextEntry.date, amount: nextEntry.type === 'expense' ? -nextEntry.amount : nextEntry.type === 'saving' ? 0 : nextEntry.amount, accountId, categoryName: nextEntry.type === 'expense' ? nextEntry.category : undefined, beforeBalance: previousBalance, afterBalance: nextBalance }), ...state.activityHistory],
      notifications: appendNotification(state.notifications, createFinanceNotification({ id: `transaction:${nextEntry.id}:${existing ? 'edited' : 'created'}`, type: nextEntry.type === 'expense' ? 'expense' : nextEntry.type === 'income' ? 'income' : 'savings', title: nextEntry.type === 'expense' ? `Expense ${existing ? 'edited' : 'added'}` : nextEntry.type === 'income' ? `Income ${existing ? 'edited' : 'received'}` : 'Savings recorded', message: nextEntry.type === 'expense' ? `${formatCurrency(nextEntry.amount)} paid from ${account?.name ?? 'account'} · ${title}` : nextEntry.type === 'income' ? `${formatCurrency(nextEntry.amount)} added to ${account?.name ?? 'account'} · ${title}` : `${formatCurrency(nextEntry.amount)} classified under ${title}`, relatedEntityType: 'transaction', relatedEntityId: nextEntry.id, priority: 'normal' })),
    }
  })
}

