      const budget = state.budgets.find((item) => item.id === id)
      if (!budget) return {}
      return { budgets: state.budgets.filter((item) => item.id !== id), activityHistory: [createActivityEvent({ category: 'budgets', action: 'deleted', entityType: 'budget', entityId: id, title: `${budget.category} budget`, description: `Removed budget for ${budget.month}`, date: `${budget.month}-01`, amount: budget.amount, categoryName: budget.category }), ...state.activityHistory], notifications: appendNotification(state.notifications, createFinanceNotification({ id: `monthly-budget:${id}:deleted`, type: 'budget_deleted', title: 'Budget deleted', message: `${budget.category} budget for ${budget.month} was removed.`, relatedEntityType: 'budget', relatedEntityId: id, priority: 'low' })) }
